// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import {Test} from "forge-std/Test.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import {ERC2771Forwarder} from "@openzeppelin/contracts/metatx/ERC2771Forwarder.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {Readable} from "../src/Readable.sol";
import {IReadable} from "../src/IReadable.sol";
import {NameRules} from "../src/NameRules.sol";

/// @dev Stands in for Circle's USDC: six decimals and EIP-2612 permit.
contract PermitUsd is ERC20, ERC20Permit {
    constructor() ERC20("USD Coin", "USDC") ERC20Permit("USD Coin") {}

    function decimals() public pure override returns (uint8) {
        return 6;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev A smart account with neither an ERC-721 receiver hook nor a way to take the native coin.
contract BareAccount {}

/// @dev A contract that accepts names sent with safeTransferFrom.
contract Vault is IERC721Receiver {
    function onERC721Received(address, address, uint256, bytes calldata) external pure override returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }
}

/// @dev A manager that, on being paid in the native coin, tries to buy a name with what it got.
contract GreedyManager {
    Readable internal immutable REGISTRY;
    uint256 internal immutable NAMESPACE;
    bool public reentered;

    constructor(Readable registry, uint256 namespaceId) {
        REGISTRY = registry;
        NAMESPACE = namespaceId;
    }

    receive() external payable {
        if (reentered) return;
        reentered = true;
        IReadable.Permit memory none;
        // Whatever it tries, it pays the full price like anyone else
        try REGISTRY.register{value: msg.value}(NAMESPACE, "9999", 1, none) {} catch {}
    }
}

/**
 * @dev The registry set up the way it launches on Base: names paid in a six-decimal dollar token
 *      with permit, Numbers at the launch prices, one extension with a manager and the first
 *      name rules, and a real OpenZeppelin forwarder trusted for gasless calls.
 */
abstract contract Fixture is Test {
    uint256 internal constant USD = 1e6;
    bytes32 internal constant PERMIT_TYPEHASH = keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");
    bytes32 internal constant FORWARD_TYPEHASH =
        keccak256("ForwardRequest(address from,address to,uint256 value,uint256 gas,uint256 nonce,uint48 deadline,bytes data)");
    bytes32 internal constant DOMAIN_TYPEHASH = keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

    Readable internal registry;
    PermitUsd internal usd;
    ERC2771Forwarder internal forwarder;
    NameRules internal rules;

    address internal owner = makeAddr("owner");
    address internal manager = makeAddr("manager");
    address internal dao = makeAddr("dao");
    address internal relayer = makeAddr("relayer");
    address internal stranger = makeAddr("stranger");

    address internal alice;
    uint256 internal aliceKey;
    address internal bob;
    uint256 internal bobKey;

    uint256 internal numbers;
    uint256 internal arc;

    IReadable.Permit internal noPermit;

    function setUp() public virtual {
        (alice, aliceKey) = makeAddrAndKey("alice");
        (bob, bobKey) = makeAddrAndKey("bob");

        usd = new PermitUsd();
        forwarder = new ERC2771Forwarder("HupForwarder");
        registry = new Readable(owner, address(forwarder));
        rules = new NameRules();

        vm.startPrank(owner);
        registry.setPaymentToken(address(usd));
        registry.setNameRules(address(rules));
        numbers = registry.addNamespace(IReadable.Kind.Number, "0", 2, 12, 8, _numberPrices(), address(0), 0, "");
        arc = registry.addNamespace(IReadable.Kind.Name, "arc", 3, 32, 0, _namePrices(), manager, 10, "{\"label\":\".arc\"}");
        vm.stopPrank();

        usd.mint(alice, 100_000 * USD);
        usd.mint(bob, 100_000 * USD);
        vm.prank(alice);
        usd.approve(address(registry), type(uint256).max);
        vm.prank(bob);
        usd.approve(address(registry), type(uint256).max);
    }

    // --- PRICES ---

    function _numberPrices() internal pure returns (uint256[] memory prices) {
        prices = new uint256[](7);
        prices[0] = 2000 * USD;
        prices[1] = 500 * USD;
        prices[2] = 100 * USD;
        prices[3] = 25 * USD;
        prices[4] = 5 * USD;
        prices[5] = 5 * USD;
        prices[6] = 1 * USD;
    }

    function _namePrices() internal pure returns (uint256[] memory prices) {
        prices = new uint256[](3);
        prices[0] = 160 * USD;
        prices[1] = 40 * USD;
        prices[2] = 5 * USD;
    }

    function _flat(uint256 price) internal pure returns (uint256[] memory prices) {
        prices = new uint256[](1);
        prices[0] = price;
    }

    // --- CALLS ---

    function _register(address who, uint256 namespaceId, string memory label) internal returns (uint256 tokenId) {
        vm.prank(who);
        tokenId = registry.register(namespaceId, label, 1, noPermit);
    }

    function _coin(uint256 coinType, bytes memory value) internal pure returns (IReadable.CoinAddress[] memory entries) {
        entries = new IReadable.CoinAddress[](1);
        entries[0] = IReadable.CoinAddress(coinType, value);
    }

    function _one(string memory label) internal pure returns (string[] memory labels) {
        labels = new string[](1);
        labels[0] = label;
    }

    function _validity(uint256 namespaceId, string memory label) internal view returns (IReadable.Validity) {
        return registry.lookup(namespaceId, label).validity;
    }

    function _assertValidity(uint256 namespaceId, string memory label, IReadable.Validity expected) internal view {
        assertEq(uint8(_validity(namespaceId, label)), uint8(expected), label);
    }

    function _expectInvalid(IReadable.Validity validity) internal {
        vm.expectRevert(abi.encodeWithSelector(IReadable.InvalidLabel.selector, validity));
    }

    // --- LABELS ---

    /// @dev `cp` as UTF-8, the way a well-formed string carries it.
    function _utf8(uint256 cp) internal pure returns (bytes memory) {
        if (cp < 0x80) return abi.encodePacked(uint8(cp));
        if (cp < 0x800) return abi.encodePacked(uint8(0xc0 | (cp >> 6)), uint8(0x80 | (cp & 0x3f)));
        if (cp < 0x10000) return abi.encodePacked(uint8(0xe0 | (cp >> 12)), uint8(0x80 | ((cp >> 6) & 0x3f)), uint8(0x80 | (cp & 0x3f)));
        return abi.encodePacked(
            uint8(0xf0 | (cp >> 18)), uint8(0x80 | ((cp >> 12) & 0x3f)), uint8(0x80 | ((cp >> 6) & 0x3f)), uint8(0x80 | (cp & 0x3f))
        );
    }

    /// @dev `body` followed by the digit that makes the whole pass the Luhn check.
    function _withCheckDigit(bytes memory body) internal pure returns (string memory) {
        uint256 sum;
        for (uint256 i = 0; i < body.length; i++) {
            uint256 digit = uint8(body[body.length - 1 - i]) - 48;
            // The check digit will sit to the right, so the body's last digit is a doubled one
            if (i % 2 == 0) {
                digit *= 2;
                if (digit > 9) digit -= 9;
            }
            sum += digit;
        }
        return string(abi.encodePacked(body, uint8(48 + ((10 - (sum % 10)) % 10))));
    }

    // --- SIGNATURES ---

    function _permit(uint256 key, uint256 amount, uint256 deadline) internal view returns (IReadable.Permit memory permit) {
        address holder = vm.addr(key);
        bytes32 structHash = keccak256(abi.encode(PERMIT_TYPEHASH, holder, address(registry), amount, usd.nonces(holder), deadline));
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(key, keccak256(abi.encodePacked("\x19\x01", usd.DOMAIN_SEPARATOR(), structHash)));
        permit = IReadable.Permit(deadline, v, r, s);
    }

    function _forwarderDomain(ERC2771Forwarder target) internal view returns (bytes32) {
        (, string memory name, string memory version, uint256 chainId, address verifying, , ) = target.eip712Domain();
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256(bytes(name)), keccak256(bytes(version)), chainId, verifying));
    }

    /// @dev `data` on the registry as a request signed by `key`, ready for a relayer to execute.
    function _request(uint256 key, bytes memory data) internal view returns (ERC2771Forwarder.ForwardRequestData memory) {
        return _requestThrough(forwarder, key, data);
    }

    function _requestThrough(ERC2771Forwarder target, uint256 key, bytes memory data)
        internal
        view
        returns (ERC2771Forwarder.ForwardRequestData memory request)
    {
        address from = vm.addr(key);
        uint48 deadline = uint48(block.timestamp + 10 minutes);
        uint256 gas = 1_000_000;
        bytes32 structHash =
            keccak256(abi.encode(FORWARD_TYPEHASH, from, address(registry), uint256(0), gas, target.nonces(from), deadline, keccak256(data)));
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(key, keccak256(abi.encodePacked("\x19\x01", _forwarderDomain(target), structHash)));
        request = ERC2771Forwarder.ForwardRequestData(from, address(registry), 0, gas, deadline, data, abi.encodePacked(r, s, v));
    }
}

test/Fork.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import {Test} from "forge-std/Test.sol";
import {ERC2771Forwarder} from "@openzeppelin/contracts/metatx/ERC2771Forwarder.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Readable} from "../src/Readable.sol";
import {IReadable} from "../src/IReadable.sol";
import {NameRules} from "../src/NameRules.sol";

interface IUsdc is IERC20 {
    function name() external view returns (string memory);
    function version() external view returns (string memory);
    function decimals() external view returns (uint8);
    function nonces(address owner) external view returns (uint256);
    function DOMAIN_SEPARATOR() external view returns (bytes32);
}

/**
 * @dev The registry against Base as it is: Circle's USDC and the Hup forwarder, both the deployed
 *      ones. Runs when BASE_RPC_URL is set, and is skipped otherwise:
 *        BASE_RPC_URL=https://mainnet.base.org forge test --match-contract ForkTest
 */
contract ForkTest is Test {
    uint256 internal constant BASE = 8453;
    IUsdc internal constant USDC = IUsdc(0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913);
    ERC2771Forwarder internal constant FORWARDER = ERC2771Forwarder(0xae95e44D2642F568D0e0Fc0d60202B55c8764567);
    // EIP-170
    uint256 internal constant CODE_LIMIT = 24_576;
    uint256 internal constant USD = 1e6;

    bytes32 internal constant PERMIT_TYPEHASH = keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");
    bytes32 internal constant FORWARD_TYPEHASH =
        keccak256("ForwardRequest(address from,address to,uint256 value,uint256 gas,uint256 nonce,uint48 deadline,bytes data)");
    bytes32 internal constant DOMAIN_TYPEHASH = keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

    Readable internal registry;
    NameRules internal rules;
    uint256 internal numbers;
    uint256 internal arc;

    address internal owner = makeAddr("owner");
    address internal relayer = makeAddr("relayer");
    address internal dao = makeAddr("dao");
    address internal buyer;
    uint256 internal buyerKey;

    IReadable.Permit internal noPermit;

    function setUp() public {
        string memory url = vm.envOr("BASE_RPC_URL", string(""));
        if (bytes(url).length == 0) {
            vm.skip(true);
            return;
        }
        vm.createSelectFork(url);
        assertEq(block.chainid, BASE, "BASE_RPC_URL is not Base");

        (buyer, buyerKey) = makeAddrAndKey("buyer");
        registry = new Readable(owner, address(FORWARDER));
        rules = new NameRules();

        uint256[] memory prices = new uint256[](7);
        prices[0] = 2000 * USD;
        prices[1] = 500 * USD;
        prices[2] = 100 * USD;
        prices[3] = 25 * USD;
        prices[4] = 5 * USD;
        prices[5] = 5 * USD;
        prices[6] = 1 * USD;

        vm.startPrank(owner);
        registry.setPaymentToken(address(USDC));
        numbers = registry.addNamespace(IReadable.Kind.Number, "0", 2, 12, 8, prices, address(0), 0, "");
        registry.setNameRules(address(rules));
        uint256[] memory namePrices = new uint256[](3);
        namePrices[0] = 160 * USD;
        namePrices[1] = 40 * USD;
        namePrices[2] = 5 * USD;
        arc = registry.addNamespace(IReadable.Kind.Name, "arc", 3, 32, 0, namePrices, address(0), 0, "");
        registry.setTreasury(dao);
        vm.stopPrank();

        deal(address(USDC), buyer, 1_000 * USD);
        vm.deal(relayer, 1 ether);
    }

    function test_WhatTheRegistryReliesOnIsThere() public view {
        assertGt(address(USDC).code.length, 0, "no USDC");
        assertEq(USDC.decimals(), 6);
        assertGt(address(FORWARDER).code.length, 0, "no forwarder");
        assertGt(CREATE2_FACTORY.code.length, 0, "no CREATE2 factory");

        (, string memory name, string memory version, uint256 chainId, address verifying, , ) = FORWARDER.eip712Domain();
        assertEq(name, "HupForwarder");
        assertEq(version, "1");
        assertEq(chainId, BASE);
        assertEq(verifying, address(FORWARDER));
    }

    function test_BothContractsFitTheCodeLimit() public view {
        assertLt(address(registry).code.length, CODE_LIMIT);
        assertLt(address(rules).code.length, CODE_LIMIT);
    }

    function test_BuysAPersianNameThroughTheRealForwarder() public {
        // ali, the joiner, reza
        string memory label = string(hex"d8b9d984db8ce2808cd8b1d8b6d8a7");
        bytes memory data = abi.encodeCall(Readable.register, (arc, label, 1, _permit(5 * USD)));
        vm.prank(relayer);
        FORWARDER.execute(_request(data));

        uint256 tokenId = registry.tokenIdOf(arc, label);
        assertEq(registry.ownerOf(tokenId), buyer);
        assertEq(registry.recordOf(tokenId).length, 6);
        assertEq(USDC.balanceOf(buyer), 995 * USD);
    }

    function test_BuysWithAnApproval() public {
        vm.startPrank(buyer);
        USDC.approve(address(registry), 100 * USD);
        uint256 tokenId = registry.register(numbers, "4242", 1, noPermit);
        vm.stopPrank();

        assertEq(registry.ownerOf(tokenId), buyer);
        assertEq(USDC.balanceOf(buyer), 900 * USD);
        assertEq(USDC.balanceOf(dao), 100 * USD);
        assertEq(USDC.balanceOf(address(registry)), 0);
    }

    function test_BuysWithAPermitOfTheRealUsdc() public {
        IReadable.Permit memory permit = _permit(100 * USD);
        vm.prank(buyer);
        uint256 tokenId = registry.register(numbers, "4242", 1, permit);

        assertEq(registry.ownerOf(tokenId), buyer);
        assertEq(USDC.balanceOf(dao), 100 * USD);
    }

    function test_BuysThroughTheRealForwarderWithNoCoin() public {
        assertEq(buyer.balance, 0);
        bytes memory data = abi.encodeCall(Readable.register, (numbers, "4242", 1, _permit(100 * USD)));

        uint256 gasBefore = gasleft();
        vm.prank(relayer);
        FORWARDER.execute(_request(data));
        emit log_named_uint("gas of a relayed registration", gasBefore - gasleft());

        uint256 tokenId = registry.tokenIdOf(numbers, "4242");
        assertEq(registry.ownerOf(tokenId), buyer);
        assertEq(registry.resolve(tokenId), buyer);
        assertEq(buyer.balance, 0);
        assertEq(USDC.balanceOf(buyer), 900 * USD);
        assertEq(USDC.balanceOf(dao), 100 * USD);
    }

    function test_RenewsThroughTheRealForwarder() public {
        vm.startPrank(buyer);
        USDC.approve(address(registry), 100 * USD);
        uint256 tokenId = registry.register(numbers, "4242", 1, noPermit);
        vm.stopPrank();
        uint64 expiresAt = registry.recordOf(tokenId).expiresAt;

        bytes memory data = abi.encodeCall(Readable.renew, (tokenId, 3, _permit(300 * USD)));
        vm.prank(relayer);
        FORWARDER.execute(_request(data));

        assertEq(registry.recordOf(tokenId).expiresAt, expiresAt + 3 * 365 days);
        assertEq(USDC.balanceOf(buyer), 600 * USD);
    }

    function test_TheRealForwarderRefusesAForgedRequest() public {
        ERC2771Forwarder.ForwardRequestData memory request =
            _request(abi.encodeCall(Readable.register, (numbers, "4242", 1, _permit(100 * USD))));
        request.from = makeAddr("someone else");

        vm.prank(relayer);
        vm.expectRevert();
        FORWARDER.execute(request);
    }

    // --- SIGNATURES ---

    function _permit(uint256 amount) internal view returns (IReadable.Permit memory) {
        uint256 deadline = block.timestamp + 10 minutes;
        bytes32 structHash = keccak256(abi.encode(PERMIT_TYPEHASH, buyer, address(registry), amount, USDC.nonces(buyer), deadline));
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(buyerKey, keccak256(abi.encodePacked("\x19\x01", USDC.DOMAIN_SEPARATOR(), structHash)));
        return IReadable.Permit(deadline, v, r, s);
    }

    function _request(bytes memory data) internal view returns (ERC2771Forwarder.ForwardRequestData memory) {
        (, string memory name, string memory version, uint256 chainId, address verifying, , ) = FORWARDER.eip712Domain();
        bytes32 domain = keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256(bytes(name)), keccak256(bytes(version)), chainId, verifying));

        uint48 deadline = uint48(block.timestamp + 10 minutes);
        uint256 gas = 1_000_000;
        bytes32 structHash =
            keccak256(abi.encode(FORWARD_TYPEHASH, buyer, address(registry), uint256(0), gas, FORWARDER.nonces(buyer), deadline, keccak256(data)));
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(buyerKey, keccak256(abi.encodePacked("\x19\x01", domain, structHash)));
        return ERC2771Forwarder.ForwardRequestData(buyer, address(registry), 0, gas, deadline, data, abi.encodePacked(r, s, v));
    }
}

test/Fuzz.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import {IReadable} from "../src/IReadable.sol";
import {Fixture} from "./Fixture.sol";

/// @dev Rules that must hold for any input, tried with random ones.
contract FuzzTest is Fixture {
    /// forge-config: default.fuzz.runs = 512
    function testFuzz_ThePriceIsSharedOutToTheLastUnit(uint96 price, uint8 managerShare, uint8 yearCount) public {
        managerShare = uint8(bound(managerShare, 0, 100));
        yearCount = uint8(bound(yearCount, 1, 10));
        price = uint96(bound(price, 1, 1_000_000_000 * USD));

        vm.startPrank(owner);
        uint256 shop = registry.addNamespace(IReadable.Kind.Name, "shop", 3, 32, 0, _flat(price), manager, managerShare, "");
        registry.setTreasury(dao);
        vm.stopPrank();

        uint256 total = uint256(price) * yearCount;
        usd.mint(alice, total);
        uint256 before = usd.balanceOf(alice);
        vm.prank(alice);
        registry.register(shop, "alice", yearCount, noPermit);

        uint256 toManager = usd.balanceOf(manager);
        uint256 toTreasury = usd.balanceOf(dao);

        assertEq(before - usd.balanceOf(alice), total, "the payer pays the price");
        assertEq(toManager + toTreasury, total, "every unit goes to someone");
        assertEq(toManager, (total * managerShare) / 100);
        assertEq(usd.balanceOf(address(registry)), 0, "nothing stays behind with a treasury set");
    }

    /// forge-config: default.fuzz.runs = 512
    function testFuzz_WithoutATreasuryTheRestStaysForWithdrawal(uint96 price, uint8 managerShare) public {
        managerShare = uint8(bound(managerShare, 0, 100));
        price = uint96(bound(price, 1, 1_000_000_000 * USD));

        vm.startPrank(owner);
        uint256 shop = registry.addNamespace(IReadable.Kind.Name, "shop", 3, 32, 0, _flat(price), manager, managerShare, "");
        vm.stopPrank();

        usd.mint(alice, price);
        vm.prank(alice);
        registry.register(shop, "alice", 1, noPermit);

        uint256 kept = usd.balanceOf(address(registry));
        assertEq(kept + usd.balanceOf(manager), price);

        vm.prank(owner);
        registry.withdraw(dao, 0);
        assertEq(usd.balanceOf(dao), kept);
        assertEq(usd.balanceOf(address(registry)), 0);
    }

    function testFuzz_ATermIsWholeYears(uint8 yearCount, uint32 start) public {
        yearCount = uint8(bound(yearCount, 1, 10));
        vm.warp(uint256(start) + 1);

        vm.prank(alice);
        uint256 tokenId = registry.register(numbers, "4242", yearCount, noPermit);
        uint256 expiresAt = registry.recordOf(tokenId).expiresAt;
        assertEq(expiresAt, block.timestamp + uint256(yearCount) * 365 days);

        // Live until its last second, in grace for thirty days, free after
        vm.warp(expiresAt - 1);
        assertEq(registry.resolve(tokenId), alice);
        vm.warp(expiresAt);
        assertEq(registry.resolve(tokenId), address(0));
        assertFalse(registry.lookup(numbers, "4242").available);
        vm.warp(expiresAt + 30 days);
        assertTrue(registry.lookup(numbers, "4242").available);
    }

    function testFuzz_OnlyOneToTenYearsAreSold(uint256 yearCount) public {
        vm.assume(yearCount == 0 || yearCount > 10);
        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(IReadable.InvalidYears.selector, yearCount));
        registry.register(numbers, "4242", yearCount, noPermit);
    }

    function testFuzz_ANumberIsItsDigits(uint256 seed, uint8 length) public view {
        length = uint8(bound(length, 2, 7));
        bytes memory digits = new bytes(length);
        for (uint256 i = 0; i < length; i++) {
            digits[i] = bytes1(uint8(48 + (uint256(keccak256(abi.encode(seed, i))) % 10)));
        }

        IReadable.NameInfo memory info = registry.lookup(numbers, string(digits));
        assertEq(uint8(info.validity), uint8(IReadable.Validity.Valid));
        assertEq(info.length, length);
        assertEq(info.tokenId, uint256(keccak256(abi.encodePacked(numbers, digits))));
    }

    function testFuzz_ANumberWithAnythingElseInItIsRefused(uint256 seed, uint8 at, uint8 stray) public view {
        vm.assume(stray < 48 || stray > 57);
        bytes memory digits = bytes("424242");
        digits[bound(at, 0, digits.length - 1)] = bytes1(stray);
        seed;

        assertEq(uint8(registry.lookup(numbers, string(digits)).validity), uint8(IReadable.Validity.InvalidCharacter));
    }

    function testFuzz_ALongNumberPassesWithItsCheckDigitAlone(uint256 seed, uint8 length) public view {
        length = uint8(bound(length, 7, 11));
        bytes memory body = new bytes(length);
        for (uint256 i = 0; i < length; i++) {
            body[i] = bytes1(uint8(48 + (uint256(keccak256(abi.encode(seed, i))) % 10)));
        }
        bytes memory good = bytes(_withCheckDigit(body));
        assertEq(uint8(registry.lookup(numbers, string(good)).validity), uint8(IReadable.Validity.Valid));

        // Any other last digit is refused
        uint8 last = uint8(good[good.length - 1]);
        good[good.length - 1] = bytes1(48 + ((last - 48 + 1 + uint8(seed % 9)) % 10));
        assertEq(uint8(registry.lookup(numbers, string(good)).validity), uint8(IReadable.Validity.InvalidCheckDigit));
    }

    /// forge-config: default.fuzz.runs = 2048
    function testFuzz_AnyBytesGetAnAnswer(bytes calldata label) public view {
        // A lookup never reverts, whatever it is handed
        IReadable.NameInfo memory name = registry.lookup(arc, string(label));
        IReadable.NameInfo memory number = registry.lookup(numbers, string(label));

        if (name.validity == IReadable.Validity.Valid) {
            assertGe(name.length, 3);
            assertLe(name.length, 32);
            assertTrue(name.available);
        }
        if (number.validity == IReadable.Validity.Valid) {
            assertEq(number.length, label.length);
        }
    }

    /// forge-config: default.fuzz.runs = 2048
    function testFuzz_AValidNameIsWellFormedText(bytes calldata label) public view {
        if (registry.lookup(arc, string(label)).validity != IReadable.Validity.Valid) return;

        // Whatever the registry takes as a name decodes as UTF-8 with no capital, space or control in it
        uint256 i;
        while (i < label.length) {
            uint8 first = uint8(label[i]);
            uint256 width = first < 0x80 ? 1 : first < 0xe0 ? 2 : first < 0xf0 ? 3 : 4;
            assertLe(i + width, label.length, "a character is cut short");
            if (width == 1) {
                // Capitals arrive and are stored lowered
                bool letter = (first >= 0x61 && first <= 0x7a) || (first >= 0x41 && first <= 0x5a);
                assertTrue(letter || (first >= 0x30 && first <= 0x39) || first == 0x2d, "a stray ASCII character");
            } else {
                assertTrue(first >= 0xc2 && first <= 0xf4, "a byte UTF-8 never starts with");
                for (uint256 k = 1; k < width; k++) assertEq(uint8(label[i + k]) & 0xc0, 0x80, "a bad continuation byte");
            }
            i += width;
        }
    }

    /// forge-config: default.fuzz.runs = 2048
    function testFuzz_TheRulesAnswerAnyBytes(bytes calldata label) public view {
        (bool valid, bytes memory normalized, uint256 length) = rules.measure(label);
        assertEq(normalized.length, label.length);
        if (valid) _assertStandsAsAName(normalized, length);
    }

    /// forge-config: default.fuzz.runs = 4096
    function testFuzz_WhatTheRulesTakeIsOneNameOnly(uint256 seed, uint8 size) public view {
        // Letters of several scripts, marks, joiners, symbols and emoji, in any order
        uint24[40] memory palette = [
            uint24(0x61), 0x62, 0x7a, 0x41, 0x30, 0x39, 0x2d, 0x2d, 0xe9, 0xdf,
            0x639, 0x644, 0x6cc, 0x631, 0x627, 0x62e, 0x621, 0x200c, 0x200c, 0x64e,
            0x651, 0x430, 0x43a, 0x441, 0x3bf, 0x3b3, 0x4f60, 0x597d, 0x30fc, 0xac00,
            0x200d, 0xfe0f, 0x301, 0x20, 0x2e, 0x1f98a, 0x6f1, 0x640, 0xe000, 0x5d0
        ];
        size = uint8(bound(size, 1, 12));
        bytes memory label;
        for (uint256 i = 0; i < size; i++) {
            label = abi.encodePacked(label, _utf8(palette[uint256(keccak256(abi.encode(seed, i))) % palette.length]));
        }

        (bool valid, bytes memory normalized, uint256 length) = rules.measure(label);
        if (!valid) return;
        _assertStandsAsAName(normalized, length);

        // Nothing the rules take carries what a reader can't see, but the joiner between letters
        for (uint256 i = 0; i + 2 < normalized.length; i++) {
            bool joiner = normalized[i] == 0xe2 && normalized[i + 1] == 0x80 && normalized[i + 2] == 0x8c;
            if (joiner) {
                assertGt(i, 0, "a joiner first");
                assertLt(i + 3, normalized.length, "a joiner last");
            }
            assertFalse(normalized[i] == 0xe2 && normalized[i + 1] == 0x80 && normalized[i + 2] == 0x8d, "a zero width joiner");
        }
        assertTrue(normalized[0] != "-" && normalized[normalized.length - 1] != "-", "a hyphen at an end");
    }

    /// @dev The form the rules store is itself taken, as the same name of the same length, and has no capital in it.
    function _assertStandsAsAName(bytes memory normalized, uint256 length) internal view {
        (bool again, bytes memory same, uint256 sameLength) = rules.measure(normalized);
        assertTrue(again, "the stored form is refused");
        assertEq(keccak256(same), keccak256(normalized), "the stored form changes when read again");
        assertEq(sameLength, length);
        assertLe(length, normalized.length);
        for (uint256 i = 0; i < normalized.length; i++) {
            assertFalse(normalized[i] >= "A" && normalized[i] <= "Z", "a capital is stored");
        }
    }

    function testFuzz_ARenewalCostsWhatTheRegistrationDid(uint8 size, uint8 yearCount) public {
        size = uint8(bound(size, 3, 32));
        yearCount = uint8(bound(yearCount, 1, 10));
        bytes memory label = new bytes(size);
        for (uint256 i = 0; i < size; i++) label[i] = "a";

        uint256 before = usd.balanceOf(alice);
        vm.prank(alice);
        uint256 tokenId = registry.register(arc, string(label), yearCount, noPermit);
        uint256 paid = before - usd.balanceOf(alice);

        // Whatever becomes of the rules
        vm.prank(owner);
        registry.setNameRules(address(0));
        before = usd.balanceOf(alice);
        vm.prank(alice);
        registry.renew(tokenId, yearCount, noPermit);
        assertEq(before - usd.balanceOf(alice), paid);
        assertEq(registry.recordOf(tokenId).length, size);
    }

    function testFuzz_TheGracePeriodStaysWithinItsBounds(uint64 period) public {
        vm.prank(owner);
        if (period < 30 days || period > 365 days) {
            vm.expectRevert(IReadable.InvalidGracePeriod.selector);
            registry.setGracePeriod(period);
            assertEq(registry.gracePeriod(), 30 days);
        } else {
            registry.setGracePeriod(period);
            assertEq(registry.gracePeriod(), period);
        }
    }

    function testFuzz_CapitalsAreTheSameName(uint256 seed) public view {
        bytes memory lower = bytes("alicebob");
        bytes memory mixed = bytes("alicebob");
        for (uint256 i = 0; i < mixed.length; i++) {
            if ((seed >> i) & 1 == 1) mixed[i] = bytes1(uint8(mixed[i]) - 32);
        }
        assertEq(registry.tokenIdOf(arc, string(mixed)), registry.tokenIdOf(arc, string(lower)));
    }

    function testFuzz_OnlyTheHolderChangesAName(address caller) public {
        uint256 tokenId = _register(alice, numbers, "4242");
        vm.assume(caller != alice && caller != address(forwarder));

        vm.startPrank(caller);
        vm.expectRevert();
        registry.setTarget(tokenId, caller);
        vm.expectRevert();
        registry.setText(tokenId, "records", "x");
        vm.expectRevert();
        registry.setAddrs(tokenId, _coin(0, hex"00"));
        vm.expectRevert();
        registry.setPrimaryName(tokenId);
        vm.expectRevert();
        registry.transferFrom(alice, caller, tokenId);
        vm.stopPrank();

        assertEq(registry.ownerOf(tokenId), alice);
        assertEq(registry.resolve(tokenId), alice);
    }

    function testFuzz_OnlyTheOwnerChangesTheRegistry(address caller) public {
        vm.assume(caller != owner && caller != address(forwarder));

        vm.startPrank(caller);
        vm.expectRevert();
        registry.setPrices(numbers, _flat(1));
        vm.expectRevert();
        registry.setPaymentToken(address(0));
        vm.expectRevert();
        registry.setTrustedForwarder(caller);
        vm.expectRevert();
        registry.setNameRules(caller);
        vm.expectRevert();
        registry.setGracePeriod(60 days);
        vm.expectRevert();
        registry.setTreasury(caller);
        vm.expectRevert();
        registry.withdraw(caller, 0);
        vm.expectRevert();
        registry.pause();
        vm.expectRevert();
        registry.adminRegister(numbers, "4242", caller, 1);
        vm.expectRevert();
        registry.transferOwnership(caller);
        vm.stopPrank();
    }

    function testFuzz_AHeldNameIsNeverSoldTwice(uint32 wait) public {
        uint256 tokenId = _register(alice, numbers, "4242");
        uint256 releasedAt = registry.recordOf(tokenId).expiresAt + registry.gracePeriod();
        vm.warp(block.timestamp + bound(wait, 0, 3 * 365 days));

        vm.prank(bob);
        if (block.timestamp < releasedAt) {
            vm.expectRevert(abi.encodeWithSelector(IReadable.NameUnavailable.selector, tokenId, uint64(releasedAt)));
            registry.register(numbers, "4242", 1, noPermit);
            assertEq(registry.ownerOf(tokenId), alice);
        } else {
            registry.register(numbers, "4242", 1, noPermit);
            assertEq(registry.ownerOf(tokenId), bob);
            assertEq(registry.balanceOf(alice), 0);
        }
    }
}

