// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import {Test} from "forge-std/Test.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IERC4906} from "@openzeppelin/contracts/interfaces/IERC4906.sol";
import {Readable} from "../src/Readable.sol";
import {IReadable} from "../src/IReadable.sol";
import {NameRules} from "../src/NameRules.sol";

contract MockUsd is ERC20 {
    constructor() ERC20("Mock USD", "MUSD") {}

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev A smart account with no ERC-721 receiver hook, like many that must still hold names.
contract PlainAccount {}

contract ReadableTest is Test {
    Readable internal registry;

    address internal owner = makeAddr("owner");
    address internal forwarder = makeAddr("forwarder");
    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");
    address internal manager = makeAddr("manager");
    address internal dao = makeAddr("dao");

    uint256 internal numbers;
    uint256 internal lyx;

    IReadable.Permit internal noPermit;

    function setUp() public {
        registry = new Readable(owner, forwarder);

        uint256[] memory numberPrices = new uint256[](7);
        numberPrices[0] = 2000 ether;
        numberPrices[1] = 500 ether;
        numberPrices[2] = 100 ether;
        numberPrices[3] = 25 ether;
        numberPrices[4] = 5 ether;
        numberPrices[5] = 5 ether;
        numberPrices[6] = 0;

        uint256[] memory namePrices = new uint256[](3);
        namePrices[0] = 160 ether;
        namePrices[1] = 40 ether;
        namePrices[2] = 5 ether;

        vm.startPrank(owner);
        registry.setNameRules(address(new NameRules()));
        numbers = registry.addNamespace(IReadable.Kind.Number, "0", 2, 12, 8, numberPrices, address(0), 0, "");
        lyx = registry.addNamespace(IReadable.Kind.Name, "lyx", 3, 32, 0, namePrices, manager, 10, "");
        vm.stopPrank();

        vm.deal(alice, 10_000 ether);
        vm.deal(bob, 10_000 ether);
    }

    function _register(address who, uint256 namespaceId, string memory label, uint256 value) internal returns (uint256) {
        vm.prank(who);
        return registry.register{value: value}(namespaceId, label, 1, noPermit);
    }

    // --- NUMBERS ---

    function test_RegistersANumber() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);

        assertEq(registry.ownerOf(tokenId), alice);
        assertEq(registry.nameOf(tokenId), "+0 4242");
        assertEq(registry.resolve(tokenId), alice);
        assertEq(registry.tokenIdOf(numbers, "4242"), tokenId);
        assertEq(registry.recordOf(tokenId).expiresAt, block.timestamp + 365 days);
        assertEq(address(registry).balance, 100 ether);
    }

    function test_RequiresTheExactPrice() public {
        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(IReadable.IncorrectPayment.selector, 100 ether, 99 ether));
        registry.register{value: 99 ether}(numbers, "4242", 1, noPermit);
    }

    function test_LongNumbersNeedAValidCheckDigit() public {
        assertEq(uint8(registry.lookup(numbers, "42421231").validity), uint8(IReadable.Validity.InvalidCheckDigit));

        IReadable.NameInfo memory info = registry.lookup(numbers, "42421230");
        assertEq(uint8(info.validity), uint8(IReadable.Validity.Valid));
        assertTrue(info.available);
        assertEq(info.pricePerYear, 0);

        uint256 tokenId = _register(alice, numbers, "42421230", 0);
        assertEq(registry.ownerOf(tokenId), alice);
    }

    function test_NumbersAreDigitsOnly() public view {
        assertEq(uint8(registry.lookup(numbers, "42a2").validity), uint8(IReadable.Validity.InvalidCharacter));
        assertEq(uint8(registry.lookup(numbers, "1").validity), uint8(IReadable.Validity.TooShort));
        assertEq(registry.lookup(numbers, "42").pricePerYear, 2000 ether);
    }

    function test_MultiYearRegistrationScalesThePrice() public {
        assertEq(registry.priceOf(numbers, "4242", 3), 300 ether);
        vm.prank(alice);
        uint256 tokenId = registry.register{value: 300 ether}(numbers, "4242", 3, noPermit);
        assertEq(registry.recordOf(tokenId).expiresAt, block.timestamp + 3 * 365 days);
    }

    // --- EMOJI ---

    function test_NamesTakeNoEmoji() public view {
        _assertInvalid(lyx, string(hex"F09FA68A")); // fox
        _assertInvalid(lyx, string(hex"616C696365F09F9A80")); // alice then rocket
        _assertInvalid(lyx, string(hex"F09F91A8E2808DF09F91A9E2808DF09F91A7")); // family ZWJ sequence
        _assertInvalid(lyx, string(hex"F09F87AEF09F87B7")); // flag pair
        _assertInvalid(lyx, string(hex"F09F918DF09F8FBD")); // thumbs up with skin tone
        _assertInvalid(lyx, string(hex"E29DA4EFB88F")); // heart with VS16
        _assertInvalid(lyx, string(hex"31EFB88FE283A3")); // keycap 1
        _assertInvalid(lyx, string(hex"616263EFB88F")); // abc asked to show as emoji
        _assertInvalid(numbers, string(hex"F09FA68A"));
    }

    // --- NAMES ---

    function test_NamesAreCaseInsensitive() public {
        uint256 tokenId = _register(alice, lyx, "Alice", 5 ether);
        assertEq(registry.nameOf(tokenId), "alice.lyx");
        assertEq(registry.tokenIdOf(lyx, "alice"), tokenId);
        assertFalse(registry.lookup(lyx, "ALICE").available);
    }

    function test_NamesKeepZwnjButBlockLookAlikes() public view {
        // Persian "ali<ZWNJ>reza": six letters, the ZWNJ adds no width
        IReadable.NameInfo memory persian = registry.lookup(lyx, string(hex"D8B9D984DB8CE2808CD8B1D8B6D8A7"));
        assertEq(uint8(persian.validity), uint8(IReadable.Validity.Valid));
        assertEq(persian.length, 6);

        _assertInvalid(lyx, string(hex"616C696365E280AE")); // right-to-left override
        _assertInvalid(lyx, string(hex"D985D8B1E2808C")); // trailing ZWNJ
        _assertInvalid(lyx, "-bad");
        _assertInvalid(lyx, "a b");
        _assertInvalid(lyx, "a.b");
    }

    function test_ManagerReceivesItsShare() public {
        _register(alice, lyx, "alice", 5 ether);
        assertEq(manager.balance, 0.5 ether);
        assertEq(address(registry).balance, 4.5 ether);
    }

    // --- EXPIRY ---

    function test_ExpiredNameWaitsOutTheGracePeriod() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);
        vm.warp(block.timestamp + 366 days);

        IReadable.NameInfo memory inGrace = registry.lookup(numbers, "4242");
        assertFalse(inGrace.available);
        assertEq(inGrace.owner, alice);
        assertEq(registry.resolve(tokenId), address(0));

        vm.prank(bob);
        vm.expectRevert();
        registry.register{value: 100 ether}(numbers, "4242", 1, noPermit);

        vm.warp(block.timestamp + 30 days);
        assertTrue(registry.lookup(numbers, "4242").available);
        _register(bob, numbers, "4242", 100 ether);
        assertEq(registry.ownerOf(tokenId), bob);
        assertEq(registry.namesOf(alice).length, 0);
    }

    function test_AnyoneCanRenewDuringGrace() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);
        uint64 expiresAt = registry.recordOf(tokenId).expiresAt;
        vm.warp(block.timestamp + 370 days);

        vm.prank(bob);
        registry.renew{value: 100 ether}(tokenId, 1, noPermit);
        assertEq(registry.recordOf(tokenId).expiresAt, expiresAt + 365 days);
        assertEq(registry.ownerOf(tokenId), alice);
    }

    function test_ExpiredNameCannotBeTransferred() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);
        vm.warp(block.timestamp + 366 days);
        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(IReadable.NameExpired.selector, tokenId));
        registry.transferFrom(alice, bob, tokenId);
    }

    // --- HOLDER SETTINGS ---

    function test_TransferRepointsTheNameAndClearsPrimary() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);
        vm.startPrank(alice);
        registry.setPrimaryName(tokenId);
        registry.setTarget(tokenId, makeAddr("agent"));
        registry.transferFrom(alice, bob, tokenId);
        vm.stopPrank();

        assertEq(registry.resolve(tokenId), bob);
        (uint256 primary, ) = registry.primaryNameOf(alice);
        assertEq(primary, 0);
        assertEq(registry.namesOf(bob)[0], tokenId);
    }

    function test_PrimaryName() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);
        vm.prank(alice);
        registry.setPrimaryName(tokenId);
        (uint256 primary, string memory name) = registry.primaryNameOf(alice);
        assertEq(primary, tokenId);
        assertEq(name, "+0 4242");

        vm.prank(bob);
        vm.expectRevert(abi.encodeWithSelector(IReadable.NotNameOwner.selector, tokenId));
        registry.setPrimaryName(tokenId);
    }

    function test_TransferLeavesTextRecordsBehind() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);
        vm.startPrank(alice);
        registry.setText(tokenId, "records", "{\"agent\":{\"payment\":\"0xA11CE\"}}");
        registry.transferFrom(alice, bob, tokenId);
        vm.stopPrank();

        assertEq(registry.text(tokenId, "records"), "");

        vm.prank(bob);
        registry.setText(tokenId, "records", "{\"name\":\"Bob\"}");
        assertEq(registry.text(tokenId, "records"), "{\"name\":\"Bob\"}");
    }

    function test_TextRecordsResetForTheNextHolder() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);
        vm.prank(alice);
        registry.setText(tokenId, "mcp", "https://agent.example/mcp");
        assertEq(registry.text(tokenId, "mcp"), "https://agent.example/mcp");

        vm.warp(block.timestamp + 400 days);
        _register(bob, numbers, "4242", 100 ether);
        assertEq(registry.text(tokenId, "mcp"), "");
    }

    // --- ADMIN ---

    function test_ReservedLabelsAreOwnerOnly() public {
        string[] memory labels = new string[](1);
        labels[0] = "007";
        vm.prank(owner);
        registry.setReserved(numbers, labels, true);

        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(IReadable.InvalidLabel.selector, IReadable.Validity.Reserved));
        registry.register{value: 500 ether}(numbers, "007", 1, noPermit);

        vm.prank(owner);
        uint256 tokenId = registry.adminRegister(numbers, "007", bob, 1);
        assertEq(registry.ownerOf(tokenId), bob);
    }

    function test_PausedNamespaceBlocksNewNamesOnly() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);
        vm.prank(owner);
        registry.updateNamespace(numbers, 2, 12, 8, true, address(0), 0, "");

        assertEq(uint8(registry.lookup(numbers, "4243").validity), uint8(IReadable.Validity.NamespacePaused));
        vm.prank(alice);
        registry.renew{value: 100 ether}(tokenId, 1, noPermit);
    }

    function test_PriceCurveMustNotRise() public {
        uint256[] memory rising = new uint256[](2);
        rising[0] = 1 ether;
        rising[1] = 2 ether;
        vm.prank(owner);
        vm.expectRevert(IReadable.InvalidPriceCurve.selector);
        registry.setPrices(numbers, rising);
    }

    function test_NamespaceNamesAreUniqueAndClean() public {
        uint256[] memory prices = new uint256[](1);
        vm.startPrank(owner);
        vm.expectRevert(abi.encodeWithSelector(IReadable.NamespaceNameTaken.selector, "lyx"));
        registry.addNamespace(IReadable.Kind.Name, "lyx", 3, 32, 0, prices, address(0), 0, "");
        vm.expectRevert(IReadable.InvalidNamespaceName.selector);
        registry.addNamespace(IReadable.Kind.Name, "Bad", 3, 32, 0, prices, address(0), 0, "");
        vm.expectRevert(IReadable.InvalidNamespaceName.selector);
        registry.addNamespace(IReadable.Kind.Number, "x1", 3, 32, 0, prices, address(0), 0, "");
        vm.stopPrank();
    }

    function test_ExtensionsTakeNoEmoji() public {
        uint256[] memory prices = new uint256[](1);
        vm.startPrank(owner);
        vm.expectRevert(IReadable.InvalidNamespaceName.selector);
        registry.addNamespace(IReadable.Kind.Name, string(hex"F09F8699"), 1, 32, 0, prices, address(0), 0, ""); // squared up!
        vm.expectRevert(IReadable.InvalidNamespaceName.selector);
        registry.addNamespace(IReadable.Kind.Name, string(hex"61F09F8699"), 1, 32, 0, prices, address(0), 0, ""); // letter then emoji
        vm.stopPrank();
    }

    function test_OnlyOwnerAdministers() public {
        uint256[] memory prices = new uint256[](1);
        vm.prank(alice);
        vm.expectRevert();
        registry.addNamespace(IReadable.Kind.Name, "hup", 3, 32, 0, prices, address(0), 0, "");
    }

    function test_WithdrawSendsTheBalance() public {
        _register(alice, numbers, "4242", 100 ether);
        address treasury = makeAddr("treasury");
        vm.prank(owner);
        registry.withdraw(treasury, 0);
        assertEq(treasury.balance, 100 ether);
    }

    // --- TREASURY ---

    function _setTreasury(address to) internal {
        vm.prank(owner);
        registry.setTreasury(to);
    }

    function test_SharesCannotPassTheWholePrice() public {
        uint256[] memory prices = new uint256[](1);
        vm.startPrank(owner);
        vm.expectRevert(IReadable.InvalidShare.selector);
        registry.updateNamespace(lyx, 3, 32, 0, false, manager, 101, "");
        vm.expectRevert(IReadable.InvalidShare.selector);
        registry.addNamespace(IReadable.Kind.Name, "arc", 3, 32, 0, prices, manager, 101, "");
        registry.updateNamespace(lyx, 3, 32, 0, false, manager, 100, "");
        vm.stopPrank();
    }

    function test_TreasuryReceivesTheRegistryShare() public {
        _setTreasury(dao);
        vm.prank(alice);
        registry.register{value: 5 ether}(lyx, "alice", 1, noPermit);

        assertEq(manager.balance, 0.5 ether);
        assertEq(dao.balance, 4.5 ether);
        assertEq(address(registry).balance, 0);
    }

    function test_PayoutThatCannotArriveFailsThePurchase() public {
        // An account that can't receive the native coin
        address deaf = address(new PlainAccount());
        _setTreasury(deaf);
        vm.prank(alice);
        vm.expectRevert(IReadable.TransferFailed.selector);
        registry.register{value: 100 ether}(numbers, "4242", 1, noPermit);

        // The owner points the treasury elsewhere and sales resume
        _setTreasury(dao);
        vm.prank(alice);
        uint256 tokenId = registry.register{value: 100 ether}(numbers, "4242", 1, noPermit);
        assertEq(registry.ownerOf(tokenId), alice);
        assertEq(dao.balance, 100 ether);
        assertEq(address(registry).balance, 0);
    }

    function test_Erc20PaymentIsSplitToo() public {
        MockUsd usd = new MockUsd();
        usd.mint(alice, 1_000 ether);
        vm.startPrank(owner);
        registry.setPaymentToken(address(usd));
        registry.setTreasury(dao);
        vm.stopPrank();

        vm.startPrank(alice);
        usd.approve(address(registry), 5 ether);
        registry.register(lyx, "alice", 1, noPermit);
        vm.stopPrank();

        assertEq(usd.balanceOf(manager), 0.5 ether);
        assertEq(usd.balanceOf(dao), 4.5 ether);
        assertEq(usd.balanceOf(address(registry)), 0);
    }

    function test_OnlyOwnerSetsTheTreasury() public {
        vm.prank(alice);
        vm.expectRevert();
        registry.setTreasury(alice);
    }

    // --- CALLERS ---

    function test_SmartAccountWithoutReceiverCanHoldNames() public {
        address account = address(new PlainAccount());
        vm.deal(account, 1_000 ether);
        uint256 tokenId = _register(account, numbers, "4242", 100 ether);
        assertEq(registry.ownerOf(tokenId), account);
    }

    function test_TrustedForwarderActsForTheSigner() public {
        uint256 tokenId = registry.tokenIdOf(numbers, "42421230");
        bytes memory call = abi.encodeCall(Readable.register, (numbers, "42421230", 1, noPermit));

        vm.prank(forwarder);
        (bool success, ) = address(registry).call(abi.encodePacked(call, alice));
        assertTrue(success);
        assertEq(registry.ownerOf(tokenId), alice);
    }

    function test_Erc20PaymentWithAllowance() public {
        MockUsd usd = new MockUsd();
        usd.mint(alice, 1_000 ether);
        vm.prank(owner);
        registry.setPaymentToken(address(usd));

        vm.startPrank(alice);
        usd.approve(address(registry), 100 ether);
        vm.expectRevert(IReadable.UnexpectedNativePayment.selector);
        registry.register{value: 1}(numbers, "4242", 1, noPermit);
        registry.register(numbers, "4242", 1, noPermit);
        vm.stopPrank();

        assertEq(usd.balanceOf(address(registry)), 100 ether);
    }

    // --- METADATA ---

    function test_TokenUriFollowsTheBaseUri() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);
        assertEq(registry.tokenURI(tokenId), "");

        vm.expectEmit(false, false, false, true);
        emit IERC4906.BatchMetadataUpdate(0, type(uint256).max);
        vm.prank(owner);
        registry.setBaseURI("https://readable.name/nft/");
        assertEq(registry.tokenURI(tokenId), string.concat("https://readable.name/nft/", vm.toString(tokenId)));

        vm.prank(owner);
        registry.setBaseURI("ipfs://bafy/");
        assertEq(registry.tokenURI(tokenId), string.concat("ipfs://bafy/", vm.toString(tokenId)));

        vm.expectRevert();
        registry.tokenURI(1);
    }

    function test_OnlyOwnerSetsTheBaseUri() public {
        vm.prank(alice);
        vm.expectRevert();
        registry.setBaseURI("https://elsewhere.example/");
    }

    function test_RenewalAnnouncesNewMetadata() public {
        uint256 tokenId = _register(alice, numbers, "4242", 100 ether);
        vm.expectEmit(false, false, false, true);
        emit IERC4906.MetadataUpdate(tokenId);
        vm.prank(alice);
        registry.renew{value: 100 ether}(tokenId, 1, noPermit);
    }

    function test_SupportsTheMetadataUpdateInterface() public view {
        assertTrue(registry.supportsInterface(0x49064906));
        assertTrue(registry.supportsInterface(0x80ac58cd)); // ERC-721
    }

    // --- HELPERS ---

    function _assertInvalid(uint256 namespaceId, string memory label) internal view {
        assertEq(uint8(registry.lookup(namespaceId, label).validity), uint8(IReadable.Validity.InvalidCharacter), label);
    }
}

test/Registration.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC4906} from "@openzeppelin/contracts/interfaces/IERC4906.sol";
import {IERC20Errors} from "@openzeppelin/contracts/interfaces/draft-IERC6093.sol";
import {IReadable} from "../src/IReadable.sol";
import {BareAccount, Fixture, GreedyManager} from "./Fixture.sol";

/// @dev register, renew and adminRegister, and the payment they collect.
contract RegistrationTest is Fixture {
    // --- REGISTER ---

    function test_Register_WritesTheRecordAndMints() public {
        uint256 tokenId = registry.tokenIdOf(numbers, "4242");

        vm.expectEmit(true, true, true, true);
        emit IReadable.NameRegistered(tokenId, numbers, "4242", alice, uint64(block.timestamp + 365 days));
        vm.prank(alice);
        uint256 minted = registry.register(numbers, "4242", 1, noPermit);

        assertEq(minted, tokenId);
        assertEq(registry.ownerOf(tokenId), alice);
        assertEq(registry.balanceOf(alice), 1);

        IReadable.Record memory record = registry.recordOf(tokenId);
        assertEq(record.namespaceId, numbers);
        assertEq(record.label, "4242");
        assertEq(record.target, alice);
        assertEq(record.registeredAt, block.timestamp);
        assertEq(record.expiresAt, block.timestamp + 365 days);

        assertEq(usd.balanceOf(address(registry)), 100 * USD);
        assertEq(usd.balanceOf(alice), 100_000 * USD - 100 * USD);
    }

    function test_Register_PricesByLength() public {
        uint256 before = usd.balanceOf(alice);
        _register(alice, numbers, "42");
        assertEq(before - usd.balanceOf(alice), 2000 * USD);

        before = usd.balanceOf(alice);
        _register(alice, numbers, "424");
        assertEq(before - usd.balanceOf(alice), 500 * USD);

        before = usd.balanceOf(alice);
        _register(alice, numbers, _withCheckDigit("4242123"));
        assertEq(before - usd.balanceOf(alice), 1 * USD);

        // Past the end of the curve the last price applies
        before = usd.balanceOf(alice);
        _register(alice, numbers, _withCheckDigit("42421234567"));
        assertEq(before - usd.balanceOf(alice), 1 * USD);
    }

    function test_Register_EveryTermFromOneToTenYears() public {
        for (uint256 yearCount = 1; yearCount <= 10; yearCount++) {
            string memory label = string.concat("55", vm.toString(yearCount + 10));
            uint256 before = usd.balanceOf(alice);
            vm.prank(alice);
            uint256 tokenId = registry.register(numbers, label, yearCount, noPermit);

            assertEq(before - usd.balanceOf(alice), 100 * USD * yearCount);
            assertEq(registry.recordOf(tokenId).expiresAt, block.timestamp + yearCount * 365 days);
        }
    }

    function test_Register_RefusesAnOddTerm() public {
        vm.startPrank(alice);
        vm.expectRevert(abi.encodeWithSelector(IReadable.InvalidYears.selector, 0));
        registry.register(numbers, "4242", 0, noPermit);
        vm.expectRevert(abi.encodeWithSelector(IReadable.InvalidYears.selector, 11));
        registry.register(numbers, "4242", 11, noPermit);
        vm.stopPrank();
    }

    function test_Register_RefusesEveryInvalidLabel() public {
        vm.startPrank(owner);
        registry.setReserved(numbers, _one("007"), true);
        vm.stopPrank();

        vm.startPrank(alice);
        _expectInvalid(IReadable.Validity.UnknownNamespace);
        registry.register(99, "4242", 1, noPermit);
        _expectInvalid(IReadable.Validity.InvalidCharacter);
        registry.register(numbers, "42a2", 1, noPermit);
        _expectInvalid(IReadable.Validity.TooShort);
        registry.register(numbers, "4", 1, noPermit);
        _expectInvalid(IReadable.Validity.TooShort);
        registry.register(numbers, "", 1, noPermit);
        _expectInvalid(IReadable.Validity.TooLong);
        registry.register(numbers, "1234567890123", 1, noPermit);
        _expectInvalid(IReadable.Validity.InvalidCheckDigit);
        registry.register(numbers, "42421231", 1, noPermit);
        _expectInvalid(IReadable.Validity.Reserved);
        registry.register(numbers, "007", 1, noPermit);
        vm.stopPrank();

        vm.prank(owner);
        registry.updateNamespace(numbers, 2, 12, 8, true, address(0), 0, "");
        vm.prank(alice);
        _expectInvalid(IReadable.Validity.NamespacePaused);
        registry.register(numbers, "4242", 1, noPermit);
    }

    function test_Register_RefusesATakenName() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        uint64 availableAt = registry.recordOf(tokenId).expiresAt + registry.gracePeriod();

        vm.prank(bob);
        vm.expectRevert(abi.encodeWithSelector(IReadable.NameUnavailable.selector, tokenId, availableAt));
        registry.register(numbers, "4242", 1, noPermit);

        // The holder can't register it twice either
        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(IReadable.NameUnavailable.selector, tokenId, availableAt));
        registry.register(numbers, "4242", 1, noPermit);
    }

    function test_Register_StopsWhileTheRegistryIsPaused() public {
        vm.prank(owner);
        registry.pause();
        vm.prank(alice);
        vm.expectRevert(Pausable.EnforcedPause.selector);
        registry.register(numbers, "4242", 1, noPermit);

        vm.prank(owner);
        registry.unpause();
        _register(alice, numbers, "4242");
    }

    function test_Register_TheLastSecondOfGraceStillBelongsToTheHolder() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        uint256 availableAt = registry.recordOf(tokenId).expiresAt + registry.gracePeriod();

        vm.warp(availableAt - 1);
        vm.prank(bob);
        vm.expectRevert(abi.encodeWithSelector(IReadable.NameUnavailable.selector, tokenId, uint64(availableAt)));
        registry.register(numbers, "4242", 1, noPermit);

        vm.warp(availableAt);
        _register(bob, numbers, "4242");
        assertEq(registry.ownerOf(tokenId), bob);
    }

    function test_Register_AReleasedNameStartsClean() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        vm.startPrank(alice);
        registry.setPrimaryName(tokenId);
        registry.setTarget(tokenId, stranger);
        registry.setText(tokenId, "records", "alice's");
        registry.setAddrs(tokenId, _coin(501, hex"a11ce0"));
        registry.approve(stranger, tokenId);
        vm.stopPrank();

        vm.warp(block.timestamp + 365 days + 30 days);
        _register(bob, numbers, "4242");

        assertEq(registry.ownerOf(tokenId), bob);
        assertEq(registry.resolve(tokenId), bob);
        assertEq(registry.text(tokenId, "records"), "");
        assertEq(registry.addr(tokenId, 501), "");
        assertEq(registry.getApproved(tokenId), address(0));
        assertEq(registry.recordOf(tokenId).registeredAt, block.timestamp);
        assertEq(registry.balanceOf(alice), 0);
        assertEq(registry.namesOf(alice).length, 0);
        assertEq(registry.namesOf(bob).length, 1);
        (uint256 primary, ) = registry.primaryNameOf(alice);
        assertEq(primary, 0);

        // What alice approved no longer moves the name
        vm.prank(stranger);
        vm.expectRevert();
        registry.transferFrom(bob, stranger, tokenId);
    }

    // --- PAYMENT IN A TOKEN ---

    function test_Payment_NeedsAnAllowanceOrAPermit() public {
        address carol = makeAddr("carol");
        usd.mint(carol, 1_000 * USD);
        vm.prank(carol);
        vm.expectRevert(abi.encodeWithSelector(IERC20Errors.ERC20InsufficientAllowance.selector, address(registry), 0, 100 * USD));
        registry.register(numbers, "4242", 1, noPermit);
    }

    function test_Payment_NeedsTheBalance() public {
        address carol = makeAddr("carol");
        usd.mint(carol, 99 * USD);
        vm.startPrank(carol);
        usd.approve(address(registry), type(uint256).max);
        vm.expectRevert(abi.encodeWithSelector(IERC20Errors.ERC20InsufficientBalance.selector, carol, 99 * USD, 100 * USD));
        registry.register(numbers, "4242", 1, noPermit);
        vm.stopPrank();
    }

    function test_Payment_RefusesTheNativeCoinWhenATokenIsSet() public {
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        vm.expectRevert(IReadable.UnexpectedNativePayment.selector);
        registry.register{value: 1}(numbers, "4242", 1, noPermit);
    }

    function test_Payment_APermitStandsInForTheApproval() public {
        (address carol, uint256 carolKey) = makeAddrAndKey("carol");
        usd.mint(carol, 1_000 * USD);
        IReadable.Permit memory permit = _permit(carolKey, 100 * USD, block.timestamp + 1 hours);

        vm.prank(carol);
        uint256 tokenId = registry.register(numbers, "4242", 1, permit);

        assertEq(registry.ownerOf(tokenId), carol);
        assertEq(usd.balanceOf(carol), 900 * USD);
        assertEq(usd.allowance(carol, address(registry)), 0);
    }

    function test_Payment_APermitSomeoneElseAlreadyUsedStillPays() public {
        (address carol, uint256 carolKey) = makeAddrAndKey("carol");
        usd.mint(carol, 1_000 * USD);
        uint256 deadline = block.timestamp + 1 hours;
        IReadable.Permit memory permit = _permit(carolKey, 100 * USD, deadline);

        // Read from the mempool and sent first by a stranger
        vm.prank(stranger);
        usd.permit(carol, address(registry), 100 * USD, deadline, permit.v, permit.r, permit.s);

        vm.prank(carol);
        uint256 tokenId = registry.register(numbers, "4242", 1, permit);
        assertEq(registry.ownerOf(tokenId), carol);
    }

    function test_Payment_ABadPermitPaysNothing() public {
        (address carol, uint256 carolKey) = makeAddrAndKey("carol");
        usd.mint(carol, 1_000 * USD);

        // Signed for less than the price
        IReadable.Permit memory short = _permit(carolKey, 99 * USD, block.timestamp + 1 hours);
        vm.prank(carol);
        vm.expectRevert(abi.encodeWithSelector(IERC20Errors.ERC20InsufficientAllowance.selector, address(registry), 0, 100 * USD));
        registry.register(numbers, "4242", 1, short);

        // Signed by someone else
        IReadable.Permit memory forged = _permit(bobKey, 100 * USD, block.timestamp + 1 hours);
        vm.prank(carol);
        vm.expectRevert(abi.encodeWithSelector(IERC20Errors.ERC20InsufficientAllowance.selector, address(registry), 0, 100 * USD));
        registry.register(numbers, "4242", 1, forged);

        // Past its deadline
        IReadable.Permit memory late = _permit(carolKey, 100 * USD, block.timestamp + 1 hours);
        vm.warp(block.timestamp + 2 hours);
        vm.prank(carol);
        vm.expectRevert(abi.encodeWithSelector(IERC20Errors.ERC20InsufficientAllowance.selector, address(registry), 0, 100 * USD));
        registry.register(numbers, "4242", 1, late);
    }

    function test_Payment_AFreeTierTakesNothing() public {
        uint256[] memory prices = new uint256[](2);
        prices[0] = 10 * USD;
        prices[1] = 0;
        vm.prank(owner);
        uint256 free = registry.addNamespace(IReadable.Kind.Name, "free", 3, 32, 0, prices, manager, 10, "");

        address carol = makeAddr("carol");
        vm.prank(carol);
        uint256 tokenId = registry.register(free, "carol", 10, noPermit);

        assertEq(registry.ownerOf(tokenId), carol);
        assertEq(usd.balanceOf(address(registry)), 0);
        assertEq(usd.balanceOf(manager), 0);
    }

    // --- THE SPLIT ---

    function test_Split_ManagerAndTreasury() public {
        vm.prank(owner);
        registry.setTreasury(dao);
        vm.prank(alice);
        registry.register(arc, "alice", 1, noPermit);

        assertEq(usd.balanceOf(manager), 0.5e6);
        assertEq(usd.balanceOf(dao), 4.5e6);
        assertEq(usd.balanceOf(address(registry)), 0);
    }

    function test_Split_WithoutATreasuryTheRegistryKeepsItsShare() public {
        vm.prank(alice);
        registry.register(arc, "alice", 1, noPermit);
        assertEq(usd.balanceOf(manager), 0.5e6);
        assertEq(usd.balanceOf(address(registry)), 4.5e6);
    }

    function test_Split_ANamespaceWithoutAManagerPaysNone() public {
        _register(alice, numbers, "4242");
        assertEq(usd.balanceOf(manager), 0);
        assertEq(usd.balanceOf(address(registry)), 100 * USD);
    }

    function test_Split_TheWholePriceCanGoToTheManager() public {
        vm.startPrank(owner);
        uint256 full = registry.addNamespace(IReadable.Kind.Name, "full", 3, 32, 0, _flat(10 * USD), manager, 100, "");
        registry.setTreasury(dao);
        vm.stopPrank();

        vm.prank(alice);
        registry.register(full, "alice", 1, noPermit);

        assertEq(usd.balanceOf(manager), 10 * USD);
        assertEq(usd.balanceOf(dao), 0);
        assertEq(usd.balanceOf(address(registry)), 0);
    }

    function test_Split_RoundsInTheRegistrysFavour() public {
        vm.prank(owner);
        uint256 odd = registry.addNamespace(IReadable.Kind.Name, "odd", 3, 32, 0, _flat(10), manager, 33, "");

        vm.prank(alice);
        registry.register(odd, "alice", 1, noPermit);

        // A third of ten base units is three; the rest stays with the registry
        assertEq(usd.balanceOf(manager), 3);
        assertEq(usd.balanceOf(address(registry)), 7);
    }

    // --- PAYMENT IN THE NATIVE COIN ---

    function _useNativeCoin() internal {
        vm.prank(owner);
        registry.setPaymentToken(address(0));
        vm.deal(alice, 1 ether);
    }

    function test_Native_WantsTheExactPrice() public {
        _useNativeCoin();
        vm.startPrank(alice);
        vm.expectRevert(abi.encodeWithSelector(IReadable.IncorrectPayment.selector, 100 * USD, 100 * USD - 1));
        registry.register{value: 100 * USD - 1}(numbers, "4242", 1, noPermit);
        vm.expectRevert(abi.encodeWithSelector(IReadable.IncorrectPayment.selector, 100 * USD, 100 * USD + 1));
        registry.register{value: 100 * USD + 1}(numbers, "4242", 1, noPermit);
        vm.expectRevert(abi.encodeWithSelector(IReadable.IncorrectPayment.selector, 100 * USD, 0));
        registry.register(numbers, "4242", 1, noPermit);

        registry.register{value: 100 * USD}(numbers, "4242", 1, noPermit);
        vm.stopPrank();
        assertEq(address(registry).balance, 100 * USD);
    }

    function test_Native_IgnoresAPermit() public {
        _useNativeCoin();
        IReadable.Permit memory permit = _permit(aliceKey, 100 * USD, block.timestamp + 1 hours);
        vm.prank(alice);
        registry.register{value: 100 * USD}(numbers, "4242", 1, permit);
        assertEq(usd.allowance(alice, address(registry)), type(uint256).max);
    }

    function test_Native_APayeeThatCannotReceiveStopsTheSale() public {
        _useNativeCoin();
        address deaf = address(new BareAccount());
        vm.prank(owner);
        registry.setTreasury(deaf);

        vm.prank(alice);
        vm.expectRevert(IReadable.TransferFailed.selector);
        registry.register{value: 100 * USD}(numbers, "4242", 1, noPermit);
    }

    function test_Native_AManagerThatCallsBackGainsNothing() public {
        _useNativeCoin();
        GreedyManager greedy = new GreedyManager(registry, numbers);
        vm.prank(owner);
        registry.updateNamespace(numbers, 2, 12, 8, false, address(greedy), 20, "");

        vm.prank(alice);
        uint256 tokenId = registry.register{value: 100 * USD}(numbers, "4242", 1, noPermit);

        assertTrue(greedy.reentered());
        assertEq(registry.ownerOf(tokenId), alice);
        // Its cut is a fifth of the price, short of the price of a name of its own
        assertEq(address(greedy).balance, 20 * USD);
        assertEq(registry.balanceOf(address(greedy)), 0);
        assertEq(address(registry).balance, 80 * USD);
    }

    // --- RENEW ---

    function test_Renew_AddsToTheCurrentExpiry() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        uint64 expiresAt = registry.recordOf(tokenId).expiresAt;
        vm.warp(block.timestamp + 100 days);

        vm.expectEmit(true, false, false, true);
        emit IReadable.NameRenewed(tokenId, expiresAt + 3 * 365 days);
        vm.expectEmit(false, false, false, true);
        emit IERC4906.MetadataUpdate(tokenId);
        vm.prank(alice);
        registry.renew(tokenId, 3, noPermit);

        assertEq(registry.recordOf(tokenId).expiresAt, expiresAt + 3 * 365 days);
        assertEq(usd.balanceOf(address(registry)), 400 * USD);
    }

    function test_Renew_AnyoneMayPayAndTheHolderKeepsTheName() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        vm.prank(bob);
        registry.renew(tokenId, 1, noPermit);

        assertEq(registry.ownerOf(tokenId), alice);
        assertEq(usd.balanceOf(bob), 100_000 * USD - 100 * USD);
    }

    function test_Renew_InGraceBringsTheNameBack() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        vm.warp(block.timestamp + 365 days + 29 days);
        assertEq(registry.resolve(tokenId), address(0));

        vm.prank(alice);
        registry.renew(tokenId, 1, noPermit);
        assertEq(registry.resolve(tokenId), alice);
    }

    function test_Renew_IsTooLateAfterGrace() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        vm.warp(block.timestamp + 365 days + 30 days);
        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(IReadable.NameExpired.selector, tokenId));
        registry.renew(tokenId, 1, noPermit);
    }

    function test_Renew_RefusesWhatIsNotThere() public {
        vm.startPrank(alice);
        vm.expectRevert(abi.encodeWithSelector(IReadable.NameNotFound.selector, 7));
        registry.renew(7, 1, noPermit);

        uint256 tokenId = registry.register(numbers, "4242", 1, noPermit);
        vm.expectRevert(abi.encodeWithSelector(IReadable.InvalidYears.selector, 0));
        registry.renew(tokenId, 0, noPermit);
        vm.expectRevert(abi.encodeWithSelector(IReadable.InvalidYears.selector, 11));
        registry.renew(tokenId, 11, noPermit);
        vm.stopPrank();
    }

    function test_Renew_PaysTheCurrentPrice() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        vm.prank(owner);
        registry.setPrices(numbers, _flat(7 * USD));

        uint256 before = usd.balanceOf(alice);
        vm.prank(alice);
        registry.renew(tokenId, 2, noPermit);
        assertEq(before - usd.balanceOf(alice), 14 * USD);
    }

    function test_Renew_GoesOnWhileItsNamespaceIsPaused() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        vm.prank(owner);
        registry.updateNamespace(numbers, 2, 12, 8, true, address(0), 0, "");
        vm.prank(alice);
        registry.renew(tokenId, 1, noPermit);
    }

    function test_Renew_OfAReservedNameGoesOn() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        vm.prank(owner);
        registry.setReserved(numbers, _one("4242"), true);
        vm.prank(alice);
        registry.renew(tokenId, 1, noPermit);
    }

    function test_Renew_SplitsThePaymentAndTakesAPermit() public {
        (address carol, uint256 carolKey) = makeAddrAndKey("carol");
        usd.mint(carol, 1_000 * USD);
        vm.prank(owner);
        registry.setTreasury(dao);
        uint256 tokenId = _register(alice, arc, "alice");
        uint256 managerBefore = usd.balanceOf(manager);
        uint256 daoBefore = usd.balanceOf(dao);

        IReadable.Permit memory permit = _permit(carolKey, 10 * USD, block.timestamp + 1 hours);
        vm.prank(carol);
        registry.renew(tokenId, 2, permit);

        assertEq(usd.balanceOf(manager) - managerBefore, 1 * USD);
        assertEq(usd.balanceOf(dao) - daoBefore, 9 * USD);
        assertEq(usd.balanceOf(carol), 990 * USD);
    }

    function test_Renew_CanReachPastTenYearsInSteps() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        uint64 expiresAt = registry.recordOf(tokenId).expiresAt;
        vm.startPrank(alice);
        registry.renew(tokenId, 10, noPermit);
        registry.renew(tokenId, 10, noPermit);
        vm.stopPrank();
        assertEq(registry.recordOf(tokenId).expiresAt, expiresAt + 20 * 365 days);
    }

    // --- ADMIN REGISTER ---

    function test_AdminRegister_GrantsWithoutPayment() public {
        vm.prank(owner);
        uint256 tokenId = registry.adminRegister(numbers, "42", bob, 5);

        assertEq(registry.ownerOf(tokenId), bob);
        assertEq(registry.resolve(tokenId), bob);
        assertEq(registry.recordOf(tokenId).expiresAt, block.timestamp + 5 * 365 days);
        assertEq(usd.balanceOf(bob), 100_000 * USD);
        assertEq(usd.balanceOf(address(registry)), 0);
    }

    function test_AdminRegister_PassesReservationsAndPauses() public {
        vm.startPrank(owner);
        registry.setReserved(numbers, _one("007"), true);
        registry.updateNamespace(numbers, 2, 12, 8, true, address(0), 0, "");
        registry.pause();
        uint256 tokenId = registry.adminRegister(numbers, "007", bob, 1);
        vm.stopPrank();
        assertEq(registry.ownerOf(tokenId), bob);
    }

    function test_AdminRegister_KeepsTheLabelRules() public {
        vm.startPrank(owner);
        _expectInvalid(IReadable.Validity.UnknownNamespace);
        registry.adminRegister(99, "4242", bob, 1);
        _expectInvalid(IReadable.Validity.InvalidCharacter);
        registry.adminRegister(numbers, "42x2", bob, 1);
        _expectInvalid(IReadable.Validity.TooShort);
        registry.adminRegister(numbers, "4", bob, 1);
        _expectInvalid(IReadable.Validity.TooLong);
        registry.adminRegister(numbers, "1234567890123", bob, 1);
        _expectInvalid(IReadable.Validity.InvalidCheckDigit);
        registry.adminRegister(numbers, "42421231", bob, 1);
        vm.expectRevert(abi.encodeWithSelector(IReadable.InvalidYears.selector, 0));
        registry.adminRegister(numbers, "4242", bob, 0);
        vm.expectRevert(abi.encodeWithSelector(IReadable.InvalidYears.selector, 11));
        registry.adminRegister(numbers, "4242", bob, 11);
        vm.expectRevert(IReadable.InvalidAddress.selector);
        registry.adminRegister(numbers, "4242", address(0), 1);
        vm.stopPrank();
    }

    function test_AdminRegister_NeverTakesAHeldName() public {
        uint256 tokenId = _register(alice, numbers, "4242");
        uint64 availableAt = registry.recordOf(tokenId).expiresAt + registry.gracePeriod();

        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(IReadable.NameUnavailable.selector, tokenId, availableAt));
        registry.adminRegister(numbers, "4242", owner, 1);

        // Nor one that expired and is still in its grace period
        vm.warp(block.timestamp + 365 days + 29 days);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(IReadable.NameUnavailable.selector, tokenId, availableAt));
        registry.adminRegister(numbers, "4242", owner, 1);
    }

    function test_AdminRegister_IsTheOwnersAlone() public {
        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, alice));
        registry.adminRegister(numbers, "4242", alice, 1);
    }
}

